package com.hbm.recipe.generic;
import com.hbm.fluid.*;
import com.mojang.serialization.*;
import com.mojang.serialization.codecs.RecordCodecBuilder;
import java.util.*;
import java.util.function.BooleanSupplier;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.ChatFormatting;
import net.minecraft.network.RegistryFriendlyByteBuf;
import net.minecraft.network.chat.Component;
import net.minecraft.network.codec.StreamCodec;
import net.minecraft.world.item.ItemStack;
public record GenericRecipeData(String name,int duration,long power,List<GenericIngredient> inputItems,List<FluidStack> inputFluids,List<GenericOutput> outputItems,List<FluidStack> outputFluids,List<String> pools,String group,ItemStack icon,boolean named,String nameWrapper,int order) {
    private static BooleanSupplier detailKey=()->false;
    public static void setDetailKey(BooleanSupplier key){detailKey=Objects.requireNonNull(key);}
    public static boolean detailsRequested(){return detailKey.getAsBoolean();}
    public static List<Component> tooltipHeader(Component title,String internalName){var lines=new ArrayList<Component>();lines.add(title.copy().withStyle(ChatFormatting.YELLOW));if(detailsRequested())lines.add(Component.translatable("gui.hbm.recipe.internal_name",internalName).withStyle(ChatFormatting.DARK_GRAY));return lines;}
    public static final Codec<FluidStack> FLUID_CODEC=RecordCodecBuilder.create(i->i.group(Codec.STRING.fieldOf("type").forGetter((FluidStack s)->s.type.getName()),Codec.INT.fieldOf("amount").forGetter(s->s.fill),Codec.INT.optionalFieldOf("pressure",0).forGetter(s->s.pressure)).apply(i,(type,amount,pressure)->new FluidStack(HbmFluids.fromName(type),amount,pressure)));
    public static final MapCodec<GenericRecipeData> MAP_CODEC=RecordCodecBuilder.mapCodec(i->i.group(Codec.STRING.fieldOf("name").forGetter(GenericRecipeData::name),Codec.INT.fieldOf("duration").forGetter(GenericRecipeData::duration),Codec.LONG.fieldOf("power").forGetter(GenericRecipeData::power),GenericIngredient.CODEC.listOf().optionalFieldOf("input_items",List.of()).forGetter(GenericRecipeData::inputItems),FLUID_CODEC.listOf().optionalFieldOf("input_fluids",List.of()).forGetter(GenericRecipeData::inputFluids),GenericOutput.CODEC.listOf().optionalFieldOf("output_items",List.of()).forGetter(GenericRecipeData::outputItems),FLUID_CODEC.listOf().optionalFieldOf("output_fluids",List.of()).forGetter(GenericRecipeData::outputFluids),Codec.STRING.listOf().optionalFieldOf("pools",List.of()).forGetter(GenericRecipeData::pools),Codec.STRING.optionalFieldOf("group","").forGetter(GenericRecipeData::group),ItemStack.OPTIONAL_CODEC.optionalFieldOf("icon",ItemStack.EMPTY).forGetter(GenericRecipeData::icon),Codec.BOOL.optionalFieldOf("named",false).forGetter(GenericRecipeData::named),Codec.STRING.optionalFieldOf("name_wrapper","").forGetter(GenericRecipeData::nameWrapper),Codec.INT.optionalFieldOf("order",0).forGetter(GenericRecipeData::order)).apply(i,GenericRecipeData::new));
    public static final Codec<GenericRecipeData> CODEC=MAP_CODEC.codec();
    public static final StreamCodec<RegistryFriendlyByteBuf,GenericRecipeData> STREAM_CODEC=StreamCodec.of((b,r)->r.encode(b),GenericRecipeData::decode);
    public GenericRecipeData{inputItems=List.copyOf(inputItems);inputFluids=copyFluids(inputFluids);outputItems=List.copyOf(outputItems);outputFluids=copyFluids(outputFluids);pools=List.copyOf(pools);}
    private static List<FluidStack> copyFluids(List<FluidStack> values){return values.stream().map(s->new FluidStack(s.type,s.fill,s.pressure)).toList();}
    public ItemStack resolvedIcon(){if(!icon.isEmpty())return icon.copy();if(!outputItems.isEmpty())return outputItems.getFirst().pool().getFirst().stack().copy();if(!outputFluids.isEmpty())return com.hbm.item.fluid.FluidIconItem.make(outputFluids.getFirst());return ItemStack.EMPTY;}
    public Component displayName(){Component value=named?Component.translatable(name):resolvedIcon().getHoverName();return nameWrapper.isEmpty()?value:Component.translatable(nameWrapper,value);}
    public List<Component> tooltip(){var lines=tooltipHeader(displayName(),name);if(!group.isEmpty())for(String line:Component.translatable("autoswitch",Component.translatable(group)).getString().split("\\$",-1))lines.add(Component.literal(line).withStyle(ChatFormatting.GOLD));if(duration>0)lines.add(Component.translatable("gui.recipe.duration").append(": "+duration/20D+"s").withStyle(ChatFormatting.RED));if(power>0)lines.add(Component.translatable("gui.recipe.consumption").append(": "+power+" HE/t").withStyle(ChatFormatting.RED));lines.add(Component.translatable("gui.recipe.input").withStyle(ChatFormatting.BOLD));for(var in:inputItems){var examples=in.examples();var display=examples.isEmpty()?new ItemStack(BuiltInRegistries.ITEM.get(ResourceLocation.fromNamespaceAndPath("hbm","nothing"))):examples.get((int)((System.currentTimeMillis()/1000L)%examples.size()));lines.add(Component.literal("  "+display.getCount()+"x ").append(display.getHoverName()).withStyle(ChatFormatting.GRAY));}for(var in:inputFluids)lines.add(fluidLabel(in));lines.add(Component.translatable("gui.recipe.output").withStyle(ChatFormatting.BOLD));for(var out:outputItems){if(out.weighted())lines.add(Component.literal("  One of:"));for(var c:out.pool())lines.add(Component.literal("  "+c.stack().getCount()+"x ").append(c.stack().getHoverName()).append(c.chance()>=1&&!out.weighted()?"":" ("+((int)(out.selectionProbability(c)*c.chance()*1000)/10F)+"%)").withStyle(ChatFormatting.GRAY));}for(var out:outputFluids)lines.add(fluidLabel(out));return lines;}
    public static Component fluidLabel(FluidStack stack){return Component.literal("  "+stack.fill+"mB ").append(stack.type.displayName()).append(stack.pressure==0?Component.empty():Component.literal(" ").append(Component.translatable("gui.recipe.atPressure")).append(" "+stack.pressure+" PU")).withStyle(ChatFormatting.BLUE);}
    public void encode(RegistryFriendlyByteBuf b){b.writeUtf(name);b.writeInt(duration);b.writeLong(power);b.writeVarInt(inputItems.size());inputItems.forEach(s->s.encode(b));writeFluids(b,inputFluids);b.writeVarInt(outputItems.size());outputItems.forEach(s->s.encode(b));writeFluids(b,outputFluids);b.writeCollection(pools,(buf,value)->buf.writeUtf(value));b.writeUtf(group);ItemStack.OPTIONAL_STREAM_CODEC.encode(b,icon);b.writeBoolean(named);b.writeUtf(nameWrapper);b.writeInt(order);}
    public static GenericRecipeData decode(RegistryFriendlyByteBuf b){String name=b.readUtf();int duration=b.readInt();long power=b.readLong();var inputs=new ArrayList<GenericIngredient>();int size=b.readVarInt();for(int i=0;i<size;i++)inputs.add(GenericIngredient.decode(b));var inFluids=readFluids(b);var outputs=new ArrayList<GenericOutput>();size=b.readVarInt();for(int i=0;i<size;i++)outputs.add(GenericOutput.decode(b));var outFluids=readFluids(b);List<String> pools=b.readList(buf->buf.readUtf());String group=b.readUtf();ItemStack icon=ItemStack.OPTIONAL_STREAM_CODEC.decode(b);return new GenericRecipeData(name,duration,power,inputs,inFluids,outputs,outFluids,pools,group,icon,b.readBoolean(),b.readUtf(),b.readInt());}
    public static void writeFluids(RegistryFriendlyByteBuf b,List<FluidStack> values){b.writeVarInt(values.size());for(var s:values){b.writeInt(s.type.getID());b.writeInt(s.fill);b.writeInt(s.pressure);}}
    public static List<FluidStack> readFluids(RegistryFriendlyByteBuf b){var list=new ArrayList<FluidStack>();int size=b.readVarInt();for(int i=0;i<size;i++)list.add(new FluidStack(HbmFluids.fromID(b.readInt()),b.readInt(),b.readInt()));return list;}
}
